     1→import { headers } from "next/headers";
     2→import { unauthorized } from "next/navigation";
     3→import { auth } from "../auth";
     4→import type { AuthPermission, AuthRole } from "../auth/auth-permissions";
     5→import { getPlanLimits } from "../auth/stripe/auth-plans";
     6→import { getSession } from "../auth/auth-user";
     7→import { logger } from "../logger";
     8→import { prisma } from "../prisma";
     9→import { getOrgActiveSubscription } from "./get-org-subscription";
    10→import { isInRoles } from "./is-in-roles";
    11→
    12→type OrgParams = {
    13→  roles?: AuthRole[];
    14→  permissions?: AuthPermission;
    15→  currentOrgId?: string;
    16→  currentOrgSlug?: string;
    17→};
    18→
    19→const getFullOrg = async (orgId: string, userId: string) => {
    20→  return prisma.organization.findUnique({
    21→    where: {
    22→      id: orgId,
    23→    },
    24→    select: {
    25→      id: true,
    26→      name: true,
    27→      slug: true,
    28→      logo: true,
    29→      metadata: true,
    30→      createdAt: true,
    31→      stripeCustomerId: true,
    32→      members: {
    33→        where: {
    34→          OR: [{ userId: userId }, { role: "owner" }],
    35→        },
    36→        select: {
    37→          createdAt: true,
    38→          id: true,
    39→          role: true,
    40→          updatedAt: true,
    41→          userId: true,
    42→          user: {
    43→            select: {
    44→              email: true,
    45→              name: true,
    46→              id: true,
    47→            },
    48→          },
    49→        },
    50→        take: 2,
    51→      },
    52→    },
    53→  });
    54→};
    55→
    56→const getOrg = async (params?: OrgParams) => {
    57→  const user = await getSession();
    58→
    59→  if (user?.session.activeOrganizationId) {
    60→    return getFullOrg(user.session.activeOrganizationId, user.session.userId);
    61→  }
    62→
    63→  if (params?.currentOrgId) {
    64→    try {
    65→      await auth.api.setActiveOrganization({
    66→        headers: await headers(),
    67→        body: {
    68→          organizationId: params.currentOrgId,
    69→        },
    70→      });
    71→
    72→      const updatedUser = await getSession();
    73→
    74→      if (updatedUser?.session.activeOrganizationId) {
    75→        return getFullOrg(
    76→          updatedUser.session.activeOrganizationId,
    77→          updatedUser.session.userId,
    78→        );
    79→      }
    80→    } catch (err) {
    81→      logger.error("Error setting active organization", err);
    82→    }
    83→  }
    84→
    85→  if (params?.currentOrgSlug) {
    86→    try {
    87→      await auth.api.setActiveOrganization({
    88→        headers: await headers(),
    89→        body: {
    90→          organizationSlug: params.currentOrgSlug,
    91→        },
    92→      });
    93→
    94→      const updatedUser = await getSession();
    95→      if (updatedUser?.session.activeOrganizationId) {
    96→        return getFullOrg(
    97→          updatedUser.session.activeOrganizationId,
    98→          updatedUser.session.userId,
    99→        );
   100→      }
   101→    } catch (err) {
   102→      logger.error("Error setting active organization", err);
   103→    }
   104→  }
   105→
   106→  const firstOrg = await prisma.organization.findFirst({
   107→    where: {
   108→      members: {
   109→        some: { userId: user?.session.userId },
   110→      },
   111→    },
   112→  });
   113→
   114→  if (firstOrg) {
   115→    await auth.api.setActiveOrganization({
   116→      headers: await headers(),
   117→      body: { organizationId: firstOrg.id },
   118→    });
   119→
   120→    const updatedUser = await getSession();
   121→    if (updatedUser?.session.activeOrganizationId) {
   122→      return getFullOrg(
   123→        updatedUser.session.activeOrganizationId,
   124→        updatedUser.session.userId,
   125→      );
   126→    }
   127→  }
   128→
   129→  return null;
   130→};
   131→
   132→export const getCurrentOrg = async (params?: OrgParams) => {
   133→  const user = await getSession();
   134→
   135→  if (!user) {
   136→    return null;
   137→  }
   138→
   139→  const org = await getOrg(params);
   140→
   141→  if (!org) {
   142→    return null;
   143→  }
   144→
   145→  const memberRoles = org.members
   146→    .filter((member) => member.userId === user.session.userId)
   147→    .map((member) => member.role);
   148→
   149→  if (
   150→    memberRoles.length === 0 ||
   151→    !isInRoles(memberRoles as AuthRole[], params?.roles)
   152→  ) {
   153→    return null;
   154→  }
   155→
   156→  if (params?.permissions) {
   157→    const hasPermission = await auth.api.hasPermission({
   158→      headers: await headers(),
   159→      body: {
   160→        permission: params.permissions,
   161→      },
   162→    });
   163→
   164→    if (!hasPermission.success) {
   165→      return null;
   166→    }
   167→  }
   168→
   169→  const [currentSubscription, owner] = await Promise.all([
   170→    getOrgActiveSubscription(org.id),
   171→    org.members.find((member) => member.role === "owner")
   172→      ? Promise.resolve(org.members.find((member) => member.role === "owner"))
   173→      : prisma.member.findFirst({
   174→          where: {
   175→            organizationId: org.id,
   176→            role: "owner",
   177→          },
