              <Typography variant="muted">{t("stats.subtitle")}</Typography>
            </CardHeader>
            <CardContent className="flex flex-col gap-3 text-sm text-muted-foreground">
              <div className="rounded-2xl border border-border/60 bg-warm-panel px-4 py-3">
                <Typography variant="small">{t("stats.items.0.label")}</Typography>
                <Typography variant="large">{t("stats.items.0.value")}</Typography>
              </div>
              <div className="rounded-2xl border border-border/60 bg-warm-panel px-4 py-3">
                <Typography variant="small">{t("stats.items.1.label")}</Typography>
                <Typography variant="large">{t("stats.items.1.value")}</Typography>
              </div>
              <div className="rounded-2xl border border-border/60 bg-warm-panel px-4 py-3">
                <Typography variant="small">{t("stats.items.2.label")}</Typography>
                <Typography variant="large">{t("stats.items.2.value")}</Typography>
              </div>
            </CardContent>
          </Card>

          <Card className="lg:col-span-2 rounded-3xl border border-border/60 bg-white/80 shadow-premium backdrop-blur">
            <CardHeader>
              <Typography variant="large">{t("list.title")}</Typography>
              <Typography variant="muted">{t("list.subtitle")}</Typography>
            </CardHeader>
            <CardContent className="flex flex-col gap-4">
              {caregivers.map((caregiver) => (
                <div
                  key={caregiver.name}
                  className="flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-border/60 bg-warm-panel px-4 py-3"
                >
                  <div>
                    <Typography variant="small">{caregiver.name}</Typography>
                    <Typography variant="muted">{caregiver.role}</Typography>
                  </div>
                  <span className="rounded-full bg-primary/10 px-3 py-1 text-xs font-semibold text-primary-darkest">
                    {caregiver.status}
                  </span>
                </div>
              ))}
            </CardContent>
          </Card>
        </div>

        <Card className="rounded-3xl border border-border/60 bg-white/80 shadow-premium backdrop-blur">
          <CardHeader>
            <Typography variant="large">{t("observations.title")}</Typography>
            <Typography variant="muted">{t("observations.subtitle")}</Typography>
          </CardHeader>
          <CardContent className="grid gap-4 md:grid-cols-2">
            {[0, 1].map((index) => (
              <div
                key={index}
                className="rounded-2xl border border-border/60 bg-warm-panel p-4"
              >
                <Typography variant="small">
                  {t(`observations.items.${index}.author`)}
                </Typography>
                <Typography variant="muted">
                  {t(`observations.items.${index}.date`)}
                </Typography>
                <Typography variant="p" className="mt-2 text-sm text-muted-foreground">
                  {t(`observations.items.${index}.content`)}
                </Typography>
              </div>
            ))}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

